  'privacy.delete.title': 'حذف بياناتي',
  'privacy.delete.text': 'يحذف نهائيًا محادثاتك وذكرياتك الخاصة (وإدخالات فهرس البحث الخاصة بها) وجلساتك الصوتية ونصوصها وتفضيلات الإشعارات وما تعلّمه ANUM منك وصناديق البريد الخاصة التي ربطتها (ويسحب ANUM صلاحيته لدى مزوّد البريد أيضًا) ومسودات البريد التي لم ترسلها وإشعارات الفريق وملفك في الفريق ووكلاءك الخاصين مع ذكرياتهم في مساحة العمل هذه، ويعيد ضبط تفضيلاتك (مثل تذكّر أشياء من محادثاتي) في كل مساحات عمل هذه المؤسسة. لا يمكن التراجع عن ذلك. نزّل بياناتك أولًا إن أردت نسخة منها.',
  'privacy.delete.keptLabel': 'ما يبقى:',
